// HasOrders applies the HasEdge predicate on the "orders" edge.
func HasOrders() predicate.VacationOffer {
	return predicate.VacationOffer(func(s *sql.Selector) {
		step := sqlgraph.NewStep(
			sqlgraph.From(Table, FieldID),
			sqlgraph.Edge(sqlgraph.O2M, true, OrdersTable, OrdersColumn),
		)
		sqlgraph.HasNeighbors(s, step)
	})
}

// HasOrdersWith applies the HasEdge predicate on the "orders" edge with a given conditions (other predicates).
func HasOrdersWith(preds ...predicate.TravelOrder) predicate.VacationOffer {
	return predicate.VacationOffer(func(s *sql.Selector) {
		step := newOrdersStep()
		sqlgraph.HasNeighborsWith(s, step, func(s *sql.Selector) {
			for _, p := range preds {
				p(s)
			}
		})
	})
}

// And groups predicates with the AND operator between them.
func And(predicates ...predicate.VacationOffer) predicate.VacationOffer {
	return predicate.VacationOffer(sql.AndPredicates(predicates...))
}

// Or groups predicates with the OR operator between them.
func Or(predicates ...predicate.VacationOffer) predicate.VacationOffer {
	return predicate.VacationOffer(sql.OrPredicates(predicates...))
}

// Not applies the not operator on the given predicate.
func Not(p predicate.VacationOffer) predicate.VacationOffer {
	return predicate.VacationOffer(sql.NotPredicates(p))
}
